mapper.insert:
INSERT INTO USER_ACCOUNT (
    USER_ID, LOGIN_ID, PASSWORD_HASH, USER_NAME, POSITION_NAME, DEPT_NAME, ROLE,
    ENABLED_YN, FAILED_COUNT, CREATED_AT
) VALUES (
    #{userId}, #{loginId}, #{passwordHash}, #{userName}, #{positionName}, #{deptName}, #{role},
    #{enabledYn}, 0, #{createdAt}
)

mapper.update:
UPDATE USER_ACCOUNT
   SET USER_NAME = #{userName}, POSITION_NAME = #{positionName}, EMP_NO = #{empNo}, JOB_SERIES = #{jobSeries},
       HIRED_ON = #{hiredOn, jdbcType=DATE}, EXTENSION = #{extension}
 WHERE USER_ID = #{userId}

mapper.select:
SELECT * FROM (
    SELECT H.HISTORY_ID, H.USER_ID, U.LOGIN_ID, U.USER_NAME, H.FROM_DEPT, H.TO_DEPT, H.MOVED_AT, H.MOVED_BY
      FROM USER_DEPT_HISTORY H
      JOIN USER_ACCOUNT U ON U.USER_ID = H.USER_ID
     ORDER BY H.MOVED_AT DESC, H.HISTORY_ID DESC
) WHERE ROWNUM <= #{limit}
